const numericSegments = (version: string): number[] =>
  version
    .split('-')[0]
    .split('.')
    .map((segment) => Number.parseInt(segment, 10));

export const isNewerVersion = (
  candidate: string,
  baseline: string,
): boolean => {
  const a = numericSegments(candidate);
  const b = numericSegments(baseline);
  const length = Math.max(a.length, b.length);
  for (let i = 0; i < length; i++) {
    const left = a[i] ?? 0;
    const right = b[i] ?? 0;
    if (Number.isNaN(left) || Number.isNaN(right)) {
      return false;
    }
    if (left !== right) {
      return left > right;
    }
  }
  return false;
};

export const isSupportedServerVersion = (
  clientVersion: string,
  serverVersion: unknown,
): serverVersion is string =>
  typeof serverVersion === 'string' &&
  /^\d+\.\d+\.\d+(?:[-+][\w.-]+)?$/.test(serverVersion) &&
  !isNewerVersion(clientVersion, serverVersion);

export const RUNTIME_UPGRADE_REQUIRED_MESSAGE =
  'Run `rivet open` to upgrade this project server before another exploration starts. The upgrade can interrupt active work; saved directions remain available.';
